/// Application-meaning domain marker.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct AppMeaningDomain;

/// Answers "same meaning?" — never "same bytes?"; built only by semantic
/// normalization of an admitted declaration.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct AppSemanticCommitment(pub Commitment<AppMeaningDomain>);

/// The byte-role marker for application-image bytes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct AppImageByteRole;

/// Proves byte equality ALONE — never semantic equivalence, interface
/// compatibility, admission, authenticity, capability, availability, or
/// live-instance identity; supplying one identity where another is required
/// is a wrong-role refusal.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct AppImageDigest(pub ByteIdentity<AppImageByteRole>);

/// The claim marker for application-image references.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct AppImageClaim;

/// A five-part reference (role + identity + version + availability +
/// integrity, riding the root evidence-reference shape) — a digest-shaped
/// value with no declared role is not a lawful reference.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct AppImageRef(pub EvidenceRef<AppImageClaim>);

/// Interface-commitment domain marker.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct InterfaceDomain;

/// Every fact a caller must rely on — anything that changes a caller's
/// lawful inputs, outputs, authority, effects, bounds, refusals, or evidence
/// participates; packaging metadata, source maps, and qualification
/// references may change without silently claiming an interface change. It
/// identifies NO bytes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct InterfaceCommitment(pub Commitment<InterfaceDomain>);

/// The identity role marker for live instances.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct InstanceRole;

/// One live coordination binding — Class D, minted only by admitted
/// activation. It steals no ownership: the runtime still owns process state
/// and checkpoints; the membrane still owns Attempts and reservations;
/// backends still own durability. Live capability authority cannot be
/// serialized out of an instance as a bearer token.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct InstanceId(Occurrence<InstanceRole>);

impl IdentityRole for InstanceId {
    const CLASS: IdentityClass = IdentityClass::Occurrence;
    const CREATION: CreationLaw = CreationLaw::FreshOpaque;
}

impl InstanceId {
    /// In-crate mint for laws. Test-gated until activation minting exists.
    #[cfg(test)]
    pub(crate) const fn for_laws(occurrence: Occurrence<InstanceRole>) -> Self {
        Self(occurrence)
    }
}

/// One activation generation — Class C, scoped to its instance, carrying
/// scope and order ONLY (no image identity in the scope bytes): an image
/// upgrade is one reason the generation order advances, and generations stay
/// ordered across it.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct ActivationGeneration(pub AuthorityPosition<InstanceId>);

/// Which image a generation activated — an auxiliary fact riding a typed
/// relation, never the ordinal's bytes.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct ActivationImageBinding {
    /// The generation.
    pub generation: ActivationGeneration,
    /// The activated image.
    pub image: AppImageRef,
}

