/// The instance lifecycle — durable and recoverable (a runtime state machine
/// plus persisted data); no transition leaves `Retired`; wrong-order,
/// wrong-generation, or foreign input yields a typed refusal, never a silent
/// drop or panic. Activation admits a live generation of an immutable image
/// without mutating it — a route update activates no authority; upgrade
/// closes every relationship BEFORE the new generation accepts work;
/// rollback erases no accepted facts and revives no retired generation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum InstanceLifecycle {
    /// Instantiated.
    Instantiated,
    /// Active.
    Active,
    /// Draining — overlapping active and draining generations preserve exact
    /// generation binding.
    Draining,
    /// Retired — terminal.
    Retired,
}

/// The application-linking validation ladder — affine typestate, statically
/// owned; `Admissible` is terminal. (The application image is used ONLY when
/// persistent composition genuinely requires it — never a universal wrapper,
/// never a requirement for the four boundary forms; the linker is a pure
/// closed-world function whose input-permutation invariance is law.)
pub const APPLICATION_VALIDATION_LADDER: [&str; 5] = [
    "untrusted-bytes",
    "bounded-decoded",
    "semantically-linked",
    "independently-reconstructed",
    "admissible",
];

