/// The three complete invocation profiles — typed configuration; unsupported
/// or contradictory combinations refuse rather than silently degrading. All
/// three execute through IDENTICAL executor semantics, differing only in
/// composition authority, lifetime, permissible effects, grant origin,
/// generation binding, and evidence role. Given the same pure program,
/// parameters, selectors, cuts, bounds, and profiles, the three produce
/// equivalent semantic values — an independent oracle, not an implementation
/// assertion — yet equivalent values never make their receipts
/// interchangeable.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum InvocationProfile {
    /// A caller-supplied or locally selected validated program, bounded
    /// one-shot — no application image, instance, or generation implied.
    DirectProgram,
    /// One admitted application interface and one live generation.
    ApplicationEntrypoint,
    /// A caller-supplied canonical PURE program under a separately admitted
    /// read-only query grant — effect refusal derived from the semantic
    /// effect posture, never a hand-maintained blacklist; a computed
    /// allow/deny/defer stays data and cannot perform an effect.
    RestrictedQuery,
}

