/// The session-direction fact itself — never a guarantee profile.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum DeliveryDirection {
    /// Sending.
    Send,
    /// Receiving.
    Receive,
}

/// Orders delivery within one session direction — NOT the authority
/// sequence, a commit point, a cursor, a checkpoint, a Turn, an HLC, or
/// federation progress.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct DeliveryIndex {
    /// The session.
    pub session: SessionId,
    /// The direction.
    pub direction: DeliveryDirection,
    /// The ordinal within that scope.
    pub index: u64,
}

/// The session's terminal.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SessionTerminal {
    /// An orderly close.
    OrderlyClose,
    /// Physical death.
    PhysicalDeath,
}

/// The session state — advances sequentially; terminal reached through
/// draining or directly on physical death, and no transition leaves it. A
/// message no current state may lawfully receive is a typed refusal, never a
/// silent drop or panic.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SessionState {
    /// Pre-negotiation.
    PreNegotiation,
    /// Negotiated.
    Negotiated,
    /// Draining.
    Draining,
    /// Terminated.
    Terminated(SessionTerminal),
}

/// One direction half's state — a half-closed half is a direction state,
/// NOT a stream terminal; "local-half-closed"/"remote-half-closed" are
/// renderings of which half closed, never third states. Closing one
/// direction never closes the other.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum DirectionState {
    /// Open.
    Open,
    /// Half-closed.
    HalfClosed,
}

/// The separate whole-stream closure fact.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum StreamClosure {
    /// Open.
    Open,
    /// Closed.
    Closed,
    /// Reset.
    Reset,
}

/// The stream state — a record of both halves plus the closure fact, NOT
/// one linear half-close enum. Whole-stream terminal requires the direction
/// closures the profile makes relevant plus terminal evidence, or an
/// explicit reset.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct StreamState {
    /// The send half.
    pub send: DirectionState,
    /// The receive half.
    pub receive: DirectionState,
    /// The whole-stream closure.
    pub closure: StreamClosure,
}

/// The delivery guarantee — AUTHORED rename (the old spelling collided with
/// the runtime home's delivery-role enum; one spelling, one meaning). The
/// remote face never calls transport delivery exactly-once: effectively-once
/// application behavior requires stable logical and effect-intent
/// identities, durable admission, and idempotency at the owning boundary — a
/// transport sequence number cannot provide it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum DeliveryGuarantee {
    /// Ephemeral; loss, duplication, and gaps per carrier; no durable
    /// resumability.
    BestEffort,
    /// Compatible sessions resume admitted progress; redelivery lawful and
    /// visible; skipping accepted history forbidden. Requires a durable
    /// acknowledged checkpoint.
    ResumableAtLeastOnce,
}

