/// The progressive acknowledgement ladder — one honest signal per stage.
/// `received` and `validated` are progress/latency evidence only; ONLY
/// `admitted` (durably in accepted ingress history, crash-survivable)
/// discharges the sender's retry duty. The wire handshake is a projection of
/// the server's durable per-claim ingress progress record, so a crash is
/// traceable to the last durably recorded stage. An admitted ingress event
/// establishes receipt of the claim and its provenance, not the truth of the
/// domain assertion carried inside it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum IngressAck {
    /// Framed, not yet validated.
    Received,
    /// Protocol/authentication/replay/role/firewall checks passed, not yet
    /// durable.
    Validated,
    /// Durably in accepted ingress history — the only retry discharge.
    Admitted,
}

/// The ack profile — NO paved-road default: the deep handshake and the
/// admitted-only single ack are equally safe because the discharge invariant
/// holds identically in both (a symmetric, safety-equivalent tradeoff earns
/// no default — the interface selects). `SingleAck` means ADMITTED-ONLY,
/// never received or validated, or a retry could infer a stronger stage than
/// was durably reached.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum AckProfile {
    /// The three-stage handshake.
    ThreeStageHandshake,
    /// One admitted-only acknowledgement.
    SingleAck,
}

/// The idempotency identity ladder — established in this preference order,
/// safe by default. Whether two byte-identical requests are one retry or two
/// intents is CLIENT INTENT, unrecoverable from content: no server-side
/// content hash may dedupe effectful ingress. The reservation token is
/// idempotency-safe ONLY when obtained through an idempotent reserve keyed
/// by a stable client nonce (repeating it recovers the SAME token — a token
/// returned only on an acknowledgement the client may never receive cannot
/// rescue the retry that needs it; this is the only lawful reservation-token
/// story). SDK keys are one per intended OPERATION INSTANCE, never per
/// source-code call site. EFFECTFUL OR STATE-CHANGING INGRESS PRESENTING
/// NONE OF THESE IS REFUSED.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum IdempotencyIdentity {
    /// A natural business key the operation already carries.
    NaturalKey,
    /// A reservation token via idempotent nonce-keyed reserve.
    ClientNonceReservationToken,
    /// An SDK- or generated-client-minted stable key per operation instance.
    SdkMintedKey,
    /// An explicit client key.
    ExplicitClientKey,
}

impl IdempotencyIdentity {
    /// The declared preference ladder.
    pub const LADDER: [Self; 4] = [
        Self::NaturalKey,
        Self::ClientNonceReservationToken,
        Self::SdkMintedKey,
        Self::ExplicitClientKey,
    ];
}

